referenceSolutions.javascript:
export function solve(headings) {
  const roots = [],
    stack = [];
  for (const h of headings) {
    const n = { id: h.id, text: h.text, children: [] };
    while (stack.length && stack[stack.length - 1].level >= h.level) stack.pop();
    if (stack.length) stack[stack.length - 1].node.children.push(n);
    else roots.push(n);
    stack.push({ level: h.level, node: n });
  }
  return roots;
}

