export function solve(headings: { id: string; level: number; text: string }[]): any {
  const roots: any[] = [],
    stack: { level: number; node: any }[] = [];
  for (const h of headings) {
    const n = { id: h.id, text: h.text, children: [] as any[] };
    while (stack.length && stack[stack.length - 1].level >= h.level) stack.pop();
    if (stack.length) stack[stack.length - 1].node.children.push(n);
    else roots.push(n);
    stack.push({ level: h.level, node: n });
  }
  return roots;
}
